# -*- coding: utf-8 -*-
"""
Вторая партия автономного конвейера — 8 статей под запросы, где выдача
проверена (WebSearch/живой Яндекс+Google) и найдена слабой: конкуренты —
тонкие лендинги/агрегаторы без экспертной структуры, ни у одного нет
таблиц/норм/формул. Проверка и генерация — tools/../workflow
kran365-seo-opportunity-articles (см. журнал воркфлоу), не выдумано вручную.

Один факт из черновика workflow ИСПРАВЛЕН перед публикацией: черновик для
uborka-snega-pogruzchikom-dvor сослался на ст. 14.1.3 КоАП РФ как на норму
про сроки уборки снега — при проверке (WebFetch) статья оказалась про
лицензирование УК, а не про содержание территории. Цифра/статья реальные,
но привязаны не к тому нарушению — цитату убрали, оставили только то, что
подтверждено (ПП РФ №491, ГОСТ Р 56195-2014).
"""

def _table(headers, rows):
    th = "".join("<th>%s</th>" % h for h in headers)
    tr = "".join("<tr>%s</tr>" % "".join("<td>%s</td>" % c for c in r) for r in rows)
    return ('<div class="ptable-wrap"><table class="ptable"><thead><tr>%s</tr></thead>'
            '<tbody>%s</tbody></table></div>') % (th, tr)


def _ul(items):
    return "<ul>%s</ul>" % "".join("<li>%s</li>" % i for i in items)


